import { brokerEventFromJson, type BrokerEvent, type JsonValue } from "@rasahq/rasa-events";
import { type EventMetadata, type RawEvent } from "../types";

type ProtoJsonSource = NonNullable<RawEvent["protoJsonSource"]>;

/**
 * Dual-read of tracker events: Mantle ProtoJSON envelopes are normalized to
 * the classic flat `RawEvent` shape at receipt, so the mapping and rendering
 * code keeps a single input format. Classic flat events pass through untouched.
 *
 * Follows the backend rule in `rasa.shared.core.events.deserialise_events`: a
 * top-level `event` key means classic flat JSON, anything else is ProtoJSON.
 * ProtoJSON is parsed with the generated `@rasahq/rasa-events` types.
 */

export type InvalidTrackerEventHandler = (error: unknown, value: unknown) => void;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isProtoJsonEvent(value: unknown): value is Record<string, unknown> {
  return isRecord(value) && !("event" in value);
}

function parseJsonDocument(document: string): unknown {
  try {
    return JSON.parse(document);
  } catch {
    // A producer bug should not hide the event; surface the raw document instead.
    return document;
  }
}

function parseJsonObject(document: string | null | undefined): Record<string, unknown> {
  if (document == null) {
    return {};
  }
  const parsed = parseJsonDocument(document);
  return isRecord(parsed) ? parsed : {};
}

function camelToSnake(name: string): string {
  return name.replace(/[A-Z]/g, (character) => `_${character.toLowerCase()}`);
}

function messageFields(message: object): Record<string, unknown> {
  const fields: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(message)) {
    if (key.startsWith("$") || typeof value === "function" || value === undefined) {
      continue;
    }
    fields[camelToSnake(key)] = value;
  }
  return fields;
}

function envelopeMetadata(event: BrokerEvent): EventMetadata {
  const metadata = parseJsonObject(event.metadata);
  if (event.sessionId) {
    metadata.session_id = event.sessionId;
  }
  return metadata as EventMetadata;
}

function payloadToFlatFields(event: BrokerEvent): Record<string, unknown> {
  if (event.payload.case === undefined || event.payload.value === undefined) {
    throw new Error("BrokerEvent envelope has no payload");
  }
  const fields = messageFields(event.payload.value);
  if (event.payload.case === "memorySet") {
    const valueJson = fields.value_json;
    delete fields.value_json;
    fields.value = typeof valueJson === "string" ? parseJsonDocument(valueJson) : valueJson;
  }
  if (event.payload.case === "toolExecuted") {
    const argumentsJson = fields.arguments_json;
    const resultJson = fields.result_json;
    delete fields.arguments_json;
    delete fields.result_json;
    fields.arguments = typeof argumentsJson === "string" ? parseJsonObject(argumentsJson) : {};
    fields.result = typeof resultJson === "string" ? parseJsonDocument(resultJson) : null;
  }
  return fields;
}

export function brokerEventToRawEvent(
  event: BrokerEvent,
  protoJsonSource: ProtoJsonSource,
): RawEvent {
  if (event.payload.case === undefined) {
    throw new Error("BrokerEvent envelope has no payload");
  }
  const rawEvent: Record<string, unknown> = {
    event: camelToSnake(event.payload.case),
    timestamp: event.timestamp,
    conversation_id: event.conversationId,
    metadata: envelopeMetadata(event),
    ...payloadToFlatFields(event),
    protoJsonSource,
  };
  if (event.eventId != null) {
    rawEvent.event_id = event.eventId;
  }
  if (event.sequence != null) {
    rawEvent.sequence = event.sequence;
  }
  return rawEvent as unknown as RawEvent;
}

export function normalizeTrackerEvent(
  value: unknown,
  onInvalid?: InvalidTrackerEventHandler,
): RawEvent | undefined {
  if (!isProtoJsonEvent(value)) {
    return value as RawEvent;
  }
  try {
    const parsed = brokerEventFromJson(value as JsonValue);
    if (parsed.payload.case === undefined) {
      onInvalid?.(new Error("BrokerEvent envelope has no payload"), value);
      return undefined;
    }
    // Keep the original wire document for replay. The generated parser drops
    // unknown fields, so the parsed message is not a faithful envelope.
    return brokerEventToRawEvent(parsed, value as ProtoJsonSource);
  } catch (error) {
    onInvalid?.(error, value);
    return undefined;
  }
}

export function normalizeTrackerEvents(
  values: readonly unknown[],
  onInvalid?: InvalidTrackerEventHandler,
): RawEvent[] {
  const rawEvents: RawEvent[] = [];
  for (const value of values) {
    const rawEvent = normalizeTrackerEvent(value, onInvalid);
    if (rawEvent !== undefined) {
      rawEvents.push(rawEvent);
    }
  }
  return rawEvents;
}

/** Dual-read `events` on a tracker payload. Non-event fields are left unchanged. */
export function normalizeTrackerPayload(
  response: unknown,
  onInvalid?: InvalidTrackerEventHandler,
): unknown {
  if (!isRecord(response) || !Array.isArray(response.events)) {
    return response;
  }
  return {
    ...response,
    events: normalizeTrackerEvents(response.events, onInvalid),
  };
}

/** The payload to send back on replay: the original wire event, never the normalized copy. */
export function toReplayEvent(rawEvent: RawEvent): RawEvent | ProtoJsonSource {
  return rawEvent.protoJsonSource ?? rawEvent;
}
